/// The entry's tag list (empty when the populator adds none).
pub fn entry_tags(net_id: i32) -> &'static [EntryTag] {
    ENTRY_TAGS
        .binary_search_by_key(&net_id, |&(id, _)| id)
        .map(|i| ENTRY_TAGS[i].1)
        .unwrap_or(&[])
}

/// `GetLowestBiomeGroupIndex` (`ContentSamples.cs:775-786`): scan the
/// common-filter list BACKWARD, return the first index whose tag the
/// entry carries; `int.MaxValue` when none matches. Only ids below
/// `COMMON_FILTER_COUNT` count (the non-filter catalog tags never match);
/// preference-wrapped rows never match (the wrap is a different object,
/// `info.IndexOf` is a reference check).
pub fn lowest_biome_group_index(net_id: i32) -> i32 {
    let tags = entry_tags(net_id);
    for i in (0..COMMON_FILTER_COUNT).rev() {
        if tags.iter().any(|t| t.tag == i as u32 && !t.preferred) {
            return i as i32;
        }
    }
    i32::MAX
}

/// `Filters.ByInfoElement.FitsFilter` (`Filters.cs:161-164`): the entry's
/// Info contains the tag singleton — preference wraps do not count.
pub fn has_tag(net_id: i32, tag: u32) -> bool {
    entry_tags(net_id)
        .iter()
        .any(|t| t.tag == tag && !t.preferred)
}

/// The `IndexOf`-or-`int.MaxValue` rank of the town/critter priority
/// lists (`ContentSamples.cs:802-820`).
fn priority_or_max(list: &[i32], net_id: i32) -> i32 {
    list.iter()
        .position(|&x| x == net_id)
        .map(|i| i as i32)
        .unwrap_or(i32::MAX)
}

/// `GetBestiaryTownPriority` (`ContentSamples.cs:802-810`).
pub fn town_priority(net_id: i32) -> i32 {
    priority_or_max(TOWN_NPC_BESTIARY_PRIORITY, net_id)
}

/// `GetBestiaryNormalGoldCritterPriority` (`ContentSamples.cs:812-820`).
pub fn gold_critter_priority(net_id: i32) -> i32 {
    priority_or_max(NORMAL_GOLD_CRITTER_BESTIARY_PRIORITY, net_id)
}

/// `GetBestiaryBossPriority` (`ContentSamples.cs:822-825`): the raw
/// `IndexOf` — -1 stays -1 (bosses sort before everything else).
pub fn boss_priority(net_id: i32) -> i32 {
    BOSS_BESTIARY_PRIORITY
        .iter()
        .position(|&x| x == net_id)
        .map(|i| i as i32)
        .unwrap_or(-1)
}

/// The entry's search aliases (empty when none).
pub fn search_aliases(net_id: i32) -> impl Iterator<Item = &'static str> {
    SEARCH_ALIASES
        .iter()
        .filter(move |&&(id, _)| id == net_id)
        .map(|&(_, a)| a)
}

